 [RuntimeInitializeOnLoadMethod]static void Boot(){bool run=Array.IndexOf(Environment.GetCommandLineArgs(),"-tsBuzkashi")>=0;
#if UNITY_EDITOR
 run|=UnityEditor.SessionState.GetBool("LWS.BuzProbe",false);UnityEditor.SessionState.SetBool("LWS.BuzProbe",false);
