 if(run){var g=new GameObject("Buzkashi full physical six-AI match acceptance");DontDestroyOnLoad(g);if(FindAnyObjectByType<SportsProbeInputIsolation>()==null)g.AddComponent<SportsProbeInputIsolation>();g.AddComponent<BuzProbe>();}}
 BuzMatch m;bool had,restored;string saved,folder;int errors;readonly StringBuilder log=new StringBuilder();void Check(bool ok,string label){log.AppendLine((ok?"PASS ":"FAIL ")+label);if(!ok)errors++;File.WriteAllText(folder+"/progress.txt",log.ToString());}void Error(string s,string stack,LogType type){if(type==LogType.Error||type==LogType.Exception){errors++;log.AppendLine("ERROR "+s);}}
 IEnumerator Start(){folder=SportsEvidencePaths.Folder("BuzkashiEvidence");yield return SportsProbeScene.Ensure<BuzMatch>("TruckBuzkashi");m=FindAnyObjectByType<BuzMatch>();yield return null;had=LWS.TruckSports.SportsPrefs.HasKey(m.PreferenceKey);saved=LWS.TruckSports.SportsPrefs.GetString(m.PreferenceKey);Application.logMessageReceived+=Error;m.AllBots();for(int i=0;i<6;i++)m.setup.players[i].difficulty=(BowlingDifficulty)(i%3);Check(m.StartMatch(),"six AI full five-minute match starts without human devices");Time.timeScale=4;float end=Time.realtimeSinceStartup+450,next=0;bool paused=false;int deliveries=0,owner=-1;while(!m.Finished&&Time.realtimeSinceStartup<end){if(m.Owner!=owner){log.AppendLine("OWNER "+m.Owner+" time="+m.Clock+" cargo="+m.cargo.position);owner=m.Owner;}if(m.Deliveries!=deliveries){deliveries=m.Deliveries;log.AppendLine("DELIVERY count="+deliveries+" score="+string.Join(",",m.score)+" time="+m.Clock);}if(!paused&&m.Owner>=0){paused=true;m.Pause();var p=m.cargo.position;float clock=m.Clock;int own=m.Owner;yield return new WaitForSecondsRealtime(.15f);Check(m.Paused&&m.cargo.position==p&&m.Clock==clock&&m.Owner==own,"pause preserves actual tow cargo score and clock");m.Resume();Time.timeScale=4;}if(Time.realtimeSinceStartup>=next){File.WriteAllText(folder+"/progress.txt",log+"LIVE clock="+m.Clock+" phase="+m.Phase+" age="+m.Age+" owner="+m.Owner+" cargo="+m.cargo.position+" recoveries="+m.Recoveries+" truckRecoveries="+m.TruckRecoveries+" attachments="+m.Attachments+" breaks="+m.Breaks+" scores="+string.Join(",",m.score)+" errors="+errors);next=Time.realtimeSinceStartup+2;}yield return null;}Check(m.Finished&&m.Winner>=0&&m.Clock>=300,"full regulation match resolves a winner with real sudden-death if tied");Check(m.Deliveries>0&&m.score[0]+m.score[1]==m.Deliveries,"actual whole cargo physical delivery scores once");Check(m.Attachments>=3,"repeated legal AI tow attachments without cargo teleport");Check(m.Breaks>0,"real opposing impacts or bounded rope force produce legal breaks");Check(m.cargoShape.bounds.size.magnitude>4&&m.floppy.Length==2,"oversized readable cargo and bounded floppy bodies present");log.AppendLine("MATCH score="+string.Join(",",m.score)+" deliveries="+m.Deliveries+" attachments="+m.Attachments+" breaks="+m.Breaks+" cargoRecoveries="+m.Recoveries+" truckRecoveries="+m.TruckRecoveries+" clock="+m.Clock);log.AppendLine("ERRORS="+errors+". Native NWH/PhysX six-truck five-minute play, physical cargo constraint and complete match; no human/hardware validation.");File.WriteAllText(folder+"/result.txt",log.ToString());Debug.Log("BUZ_PROBE_COMPLETE "+log);Restore();if(!Application.isEditor)Application.Quit(errors==0?0:2);}
 void Restore(){if(restored)return;restored=true;Application.logMessageReceived-=Error;if(m!=null){m.SetupScreen();if(had)LWS.TruckSports.SportsPrefs.SetString(m.PreferenceKey,saved);else LWS.TruckSports.SportsPrefs.DeleteKey(m.PreferenceKey);LWS.TruckSports.SportsPrefs.Save();}Time.timeScale=1;}void OnDestroy(){Restore();}
